const app = require('./app');
const supertest = require('supertest');

// Test for the POST /check endpoint
describe('POST /check', () => {
  it('should evaluate a simple rule', async () => {
    const response = await supertest(app)
      .post('/check')
      .send({
        rule: 'ctx.amount > 100',
        context: { amount: 150 }
      })
      .expect(200);

    expect(response.body.result).toBe(true);
  });

  it('should evaluate a false rule', async () => {
    const response = await supertest(app)
      .post('/check')
      .send({
        rule: 'ctx.amount < 100',
        context: { amount: 150 }
      })
      .expect(200);

    expect(response.body.result).toBe(false);
  });

  it('should handle complex rules', async () => {
    const response = await supertest(app)
      .post('/check')
      .send({
        rule: 'ctx.user.age >= 18 && ctx.user.name === "Alice"',
        context: { 
          user: {
            age: 25,
            name: "Alice"
          }
        }
      })
      .expect(200);

    expect(response.body.result).toBe(true);
  });

  it('should handle errors gracefully', async () => {
    const response = await supertest(app)
      .post('/check')
      .send({
        rule: 'ctx.nonexistent.property > 100',
        context: {}
      })
      .expect(400);

    expect(response.body.error).toBeDefined();
  });
});

